// Drizzle schema for the "core" PostgreSQL schema. Source: docs/architecture.md section 4.3.
// Ids are UUIDv7 generated by the application (PGlite, used in tests, has no uuidv7()).
// Amounts are plain JS numbers: XOF, sat and msat stay far below 2^53. Use @selly/money for arithmetic.
import { sql } from 'drizzle-orm';
import {
  bigint,
  boolean,
  check,
  customType,
  date,
  index,
  integer,
  jsonb,
  pgSchema,
  primaryKey,
  smallint,
  text,
  timestamp,
  unique,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';
import { uuidv7 } from 'uuidv7';

export const core = pgSchema('core');

const citext = customType<{ data: string }>({ dataType: () => 'citext' });
// PGlite returns a Uint8Array and node-postgres a Buffer: always hand out a Buffer.
const bytea = customType<{ data: Buffer; driverData: Uint8Array }>({
  dataType: () => 'bytea',
  fromDriver: (v) => Buffer.from(v),
});
const tsvector = customType<{ data: string }>({ dataType: () => 'tsvector' });

const id = () =>
  uuid()
    .primaryKey()
    .$defaultFn(() => uuidv7());
const ts = (name: string) => timestamp(name, { withTimezone: true });
const createdAt = () => ts('created_at').notNull().defaultNow();
const num = (name: string) => bigint(name, { mode: 'number' });

export const currency = core.enum('currency', ['XOF', 'SAT']);
export const channel = core.enum('channel', ['whatsapp', 'instagram', 'web']);
export const orderStatus = core.enum('order_status', [
  'pending_payment',
  'paid',
  'fulfilled',
  'cancelled',
  'expired',
]);
export const invoiceStatus = core.enum('invoice_status', [
  'pending',
  'settled',
  'expired',
  'cancelled',
]);

// ---------------------------------------------------------------- vendors and identity

export const vendors = core.table(
  'vendors',
  {
    id: id(),
    displayName: text('display_name').notNull(),
    slug: citext('slug').notNull().unique(),
    contactWhatsappE164: text('contact_whatsapp_e164'),
    locale: text('locale').notNull().default('fr-SN'),
    settings: jsonb('settings').$type<Record<string, unknown>>().notNull().default({}),
    status: text('status', { enum: ['active', 'suspended'] })
      .notNull()
      .default('active'),
    createdAt: createdAt(),
    updatedAt: ts('updated_at').notNull().defaultNow(),
  },
  (t) => [
    check('vendors_display_name_len', sql`length(${t.displayName}) between 2 and 60`),
    check('vendors_slug_format', sql`${t.slug}::text ~ '^[a-z0-9][a-z0-9-]{1,38}[a-z0-9]$'`),
    check(
      'vendors_whatsapp_format',
      sql`${t.contactWhatsappE164} is null or ${t.contactWhatsappE164} ~ '^\\+[1-9][0-9]{7,14}$'`,
    ),
  ],
);

export const vendorKeys = core.table(
  'vendor_keys',
  {
    pubkey: text('pubkey').primaryKey(),
    vendorId: uuid('vendor_id')
      .notNull()
      .references(() => vendors.id),
    label: text('label'),
    createdAt: createdAt(),
    lastUsedAt: ts('last_used_at'),
    revokedAt: ts('revoked_at'),
  },
  (t) => [
    check('vendor_keys_pubkey_hex', sql`${t.pubkey} ~ '^[0-9a-f]{64}$'`),
    index('vendor_keys_by_vendor').on(t.vendorId).where(sql`${t.revokedAt} is null`),
  ],
);

export const nostrChallenges = core.table('nostr_challenges', {
  id: id(),
  challenge: text('challenge').notNull().unique(),
  purpose: text('purpose', { enum: ['sign_in', 'step_up', 'add_key'] }).notNull(),
  sessionId: uuid('session_id'),
  expiresAt: ts('expires_at').notNull(),
  usedAt: ts('used_at'),
  createdAt: createdAt(),
});

export const vendorSessions = core.table('vendor_sessions', {
  id: id(),
  pubkey: text('pubkey').notNull(),
  vendorId: uuid('vendor_id').references(() => vendors.id),
  tokenHash: bytea('token_hash').notNull().unique(),
  deviceLabel: text('device_label'),
  stepUpAt: ts('step_up_at'),
  lastSeenAt: ts('last_seen_at').notNull().defaultNow(),
  expiresAt: ts('expires_at').notNull(),
  revokedAt: ts('revoked_at'),
  createdAt: createdAt(),
});

// ---------------------------------------------------------------- wallets

export const walletConnections = core.table(
  'wallet_connections',
  {
    id: id(),
    owner: text('owner', { enum: ['vendor', 'platform'] })
      .notNull()
      .default('vendor'),
    vendorId: uuid('vendor_id').references(() => vendors.id),
    kind: text('kind', { enum: ['nwc', 'lightning_address'] }).notNull(),
    uriCiphertext: bytea('uri_ciphertext'),
    keyVersion: smallint('key_version'),
    walletPubkey: text('wallet_pubkey'),
    clientPubkey: text('client_pubkey'),
    relays: text('relays').array().notNull().default(sql`'{}'`),
    methods: text('methods').array().notNull().default(sql`'{}'`),
    notifications: boolean('notifications').notNull().default(false),
    encryption: text('encryption'),
    lud16: text('lud16'),
    status: text('status', { enum: ['active', 'degraded', 'revoked'] })
      .notNull()
      .default('active'),
    lastOkAt: ts('last_ok_at'),
    lastError: text('last_error'),
    createdAt: createdAt(),
    revokedAt: ts('revoked_at'),
  },
  (t) => [
    check('wallet_owner_vendor', sql`(${t.owner} = 'vendor') = (${t.vendorId} is not null)`),
    uniqueIndex('wallet_connections_one_live')
      .on(t.vendorId)
      .where(sql`${t.status} <> 'revoked' and ${t.owner} = 'vendor'`),
    uniqueIndex('wallet_connections_one_platform')
      .on(sql`(true)`)
      .where(sql`${t.status} <> 'revoked' and ${t.owner} = 'platform'`),
  ],
);

// ---------------------------------------------------------------- catalog and stock

export const products = core.table(
  'products',
  {
    id: id(),
    vendorId: uuid('vendor_id')
      .notNull()
      .references(() => vendors.id),
    title: text('title').notNull(),
    // URL part of the product page: /s/{store}/p/{slug}. Unique per vendor.
    slug: text('slug').notNull(),
    description: text('description').notNull().default(''),
    category: text('category'),
    priceAmount: num('price_amount').notNull(),
    priceCurrency: currency('price_currency').notNull().default('XOF'),
    status: text('status', { enum: ['active', 'hidden', 'archived'] })
      .notNull()
      .default('active'),
    search: tsvector('search').generatedAlwaysAs(
      sql`to_tsvector('simple', public.unaccent_i(title || ' ' || description))`,
    ),
    createdAt: createdAt(),
    updatedAt: ts('updated_at').notNull().defaultNow(),
  },
  (t) => [
    check('products_title_len', sql`length(${t.title}) between 2 and 120`),
    check('products_price_positive', sql`${t.priceAmount} > 0`),
    unique('products_vendor_slug').on(t.vendorId, t.slug),
    index('products_by_vendor').on(t.vendorId, t.status),
    index('products_search').using('gin', t.search),
    index('products_title_trgm').using('gin', sql`public.unaccent_i(${t.title}) gin_trgm_ops`),
  ],
);

export const productVariants = core.table(
  'product_variants',
  {
    id: id(),
    productId: uuid('product_id')
      .notNull()
      .references(() => products.id, { onDelete: 'cascade' }),
    sku: text('sku'),
    options: jsonb('options').$type<Record<string, string>>().notNull().default({}),
    priceOverride: num('price_override'),
    onHand: integer('on_hand').notNull().default(0),
    reserved: integer('reserved').notNull().default(0),
  },
  (t) => [
    check(
      'variants_price_override_positive',
      sql`${t.priceOverride} is null or ${t.priceOverride} > 0`,
    ),
    check('variants_on_hand_nonneg', sql`${t.onHand} >= 0`),
    check('variants_reserved_nonneg', sql`${t.reserved} >= 0`),
    check('variants_reserved_le_on_hand', sql`${t.reserved} <= ${t.onHand}`),
    unique('variants_unique_options').on(t.productId, t.options),
  ],
);

export const productImages = core.table('product_images', {
  id: id(),
  productId: uuid('product_id')
    .notNull()
    .references(() => products.id, { onDelete: 'cascade' }),
  storageKey: text('storage_key').notNull(),
  width: integer('width').notNull(),
  height: integer('height').notNull(),
  dominant: text('dominant'),
  position: smallint('position').notNull().default(0),
});

export const inventoryMovements = core.table(
  'inventory_movements',
  {
    id: id(),
    variantId: uuid('variant_id')
      .notNull()
      .references(() => productVariants.id),
    deltaOnHand: integer('delta_on_hand').notNull().default(0),
    deltaReserved: integer('delta_reserved').notNull().default(0),
    reason: text('reason', {
      enum: ['restock', 'adjustment', 'reserve', 'release', 'sale', 'return'],
    }).notNull(),
    orderId: uuid('order_id'),
    draftId: uuid('draft_id'),
    actor: text('actor').notNull(),
    createdAt: createdAt(),
  },
  (t) => [index('inventory_movements_by_variant').on(t.variantId, t.createdAt)],
);

// ---------------------------------------------------------------- customers, rates, orders

export const customers = core.table('customers', {
  id: id(),
  vendorId: uuid('vendor_id')
    .notNull()
    .references(() => vendors.id),
  displayName: text('display_name'),
  phoneE164: text('phone_e164'),
  createdAt: createdAt(),
});

export const customerIdentities = core.table(
  'customer_identities',
  {
    vendorId: uuid('vendor_id')
      .notNull()
      .references(() => vendors.id),
    channel: channel('channel').notNull(),
    externalId: text('external_id').notNull(),
    customerId: uuid('customer_id')
      .notNull()
      .references(() => customers.id),
  },
  (t) => [primaryKey({ columns: [t.vendorId, t.channel, t.externalId] })],
);

export const rateQuotes = core.table(
  'rate_quotes',
  {
    id: id(),
    // Centi-francs per BTC, as an integer: 59,036,130.00 XOF is 5903613000.
    xofPerBtcCents: num('xof_per_btc_cents').notNull(),
    source: text('source').notNull(),
    inputs: jsonb('inputs').$type<unknown>().notNull(),
    fetchedAt: ts('fetched_at').notNull(),
    validUntil: ts('valid_until').notNull(),
  },
  (t) => [check('rate_quotes_positive', sql`${t.xofPerBtcCents} > 0`)],
);

export const orders = core.table(
  'orders',
  {
    id: id(),
    vendorId: uuid('vendor_id')
      .notNull()
      .references(() => vendors.id),
    customerId: uuid('customer_id')
      .notNull()
      .references(() => customers.id),
    number: text('number').notNull(),
    publicToken: text('public_token').notNull().unique(),
    channel: channel('channel').notNull(),
    conversationRef: text('conversation_ref'),
    status: orderStatus('status').notNull().default('pending_payment'),
    attention: text('attention', { enum: ['paid_without_stock', 'paid_twice'] }),
    pricingCurrency: currency('pricing_currency').notNull(),
    subtotalXof: num('subtotal_xof').notNull(),
    deliveryFeeXof: num('delivery_fee_xof').notNull().default(0),
    discountXof: num('discount_xof').notNull().default(0),
    totalXof: num('total_xof').notNull(),
    totalMsat: num('total_msat').notNull(),
    rateQuoteId: uuid('rate_quote_id').references(() => rateQuotes.id),
    delivery: jsonb('delivery').$type<Record<string, unknown>>().notNull().default({}),
    expiresAt: ts('expires_at').notNull(),
    paidAt: ts('paid_at'),
    fulfilledAt: ts('fulfilled_at'),
    cancelledAt: ts('cancelled_at'),
    cancelReason: text('cancel_reason'),
    createdAt: createdAt(),
    updatedAt: ts('updated_at').notNull().defaultNow(),
  },
  (t) => [
    check('orders_total_positive', sql`${t.totalXof} > 0`),
    check('orders_msat_whole_sats', sql`${t.totalMsat} > 0 and ${t.totalMsat} % 1000 = 0`),
    unique('orders_vendor_number').on(t.vendorId, t.number),
    index('orders_vendor_status').on(t.vendorId, t.status, t.createdAt.desc()),
  ],
);

export const orderItems = core.table(
  'order_items',
  {
    id: id(),
    orderId: uuid('order_id')
      .notNull()
      .references(() => orders.id, { onDelete: 'cascade' }),
    variantId: uuid('variant_id')
      .notNull()
      .references(() => productVariants.id),
    quantity: integer('quantity').notNull(),
    unitPriceAmount: num('unit_price_amount').notNull(),
    priceCurrency: currency('price_currency').notNull(),
    titleSnapshot: text('title_snapshot').notNull(),
    optionsSnapshot: jsonb('options_snapshot')
      .$type<Record<string, string>>()
      .notNull()
      .default({}),
  },
  (t) => [check('order_items_quantity_range', sql`${t.quantity} between 1 and 50`)],
);

export const invoices = core.table(
  'invoices',
  {
    id: id(),
    orderId: uuid('order_id')
      .notNull()
      .references(() => orders.id),
    vendorId: uuid('vendor_id')
      .notNull()
      .references(() => vendors.id),
    walletConnectionId: uuid('wallet_connection_id').references(() => walletConnections.id),
    source: text('source', { enum: ['nwc', 'lnurl'] }).notNull(),
    bolt11: text('bolt11').notNull(),
    paymentHash: text('payment_hash').notNull(),
    amountMsat: num('amount_msat').notNull(),
    description: text('description').notNull(),
    verifyUrl: text('verify_url'),
    status: invoiceStatus('status').notNull().default('pending'),
    expiresAt: ts('expires_at').notNull(),
    settledAt: ts('settled_at'),
    preimage: text('preimage'),
    createdAt: createdAt(),
  },
  (t) => [
    check('invoices_hash_hex', sql`${t.paymentHash} ~ '^[0-9a-f]{64}$'`),
    check('invoices_amount_positive', sql`${t.amountMsat} > 0`),
    unique('invoices_vendor_hash').on(t.vendorId, t.paymentHash),
    index('invoices_by_order').on(t.orderId),
    index('invoices_pending_expiry').on(t.expiresAt).where(sql`${t.status} = 'pending'`),
  ],
);

// ---------------------------------------------------------------- subscriptions

export const plans = core.table('plans', {
  id: text('id').primaryKey(),
  name: text('name').notNull(),
  monthlyPriceSat: num('monthly_price_sat').notNull(),
  periodPrices: jsonb('period_prices').$type<Record<string, number>>().notNull(),
  limits: jsonb('limits').$type<Record<string, unknown>>().notNull(),
  active: boolean('active').notNull().default(true),
  sort: smallint('sort').notNull(),
  updatedAt: ts('updated_at').notNull().defaultNow(),
});

export const subscriptions = core.table(
  'subscriptions',
  {
    id: id(),
    vendorId: uuid('vendor_id')
      .notNull()
      .unique()
      .references(() => vendors.id),
    planId: text('plan_id')
      .notNull()
      .references(() => plans.id),
    // A plan bought to start later: after the trial, or a lower plan from the end of the period.
    nextPlanId: text('next_plan_id').references(() => plans.id),
    nextPlanAt: ts('next_plan_at'),
    status: text('status', { enum: ['trialing', 'active', 'grace', 'suspended'] }).notNull(),
    // Set once, when the vendor starts the free trial.
    trialEndsAt: ts('trial_ends_at'),
    currentPeriodStart: ts('current_period_start').notNull(),
    currentPeriodEnd: ts('current_period_end').notNull(),
    graceEndsAt: ts('grace_ends_at'),
    createdAt: createdAt(),
    updatedAt: ts('updated_at').notNull().defaultNow(),
  },
  (t) => [
    index('subscriptions_expiring')
      .on(t.currentPeriodEnd)
      .where(sql`${t.status} in ('trialing', 'active', 'grace')`),
  ],
);

export const subscriptionInvoices = core.table(
  'subscription_invoices',
  {
    id: id(),
    vendorId: uuid('vendor_id')
      .notNull()
      .references(() => vendors.id),
    // Null until the first payment of a vendor who never had a subscription creates one.
    subscriptionId: uuid('subscription_id').references(() => subscriptions.id),
    planId: text('plan_id')
      .notNull()
      .references(() => plans.id),
    months: smallint('months').notNull(),
    listPriceSat: num('list_price_sat').notNull(),
    creditSat: num('credit_sat').notNull().default(0),
    amountSat: num('amount_sat').notNull(),
    // The platform wallet. Null for invoices of the fake provider (development and tests).
    walletConnectionId: uuid('wallet_connection_id').references(() => walletConnections.id),
    source: text('source', { enum: ['nwc', 'lnurl'] }).notNull(),
    bolt11: text('bolt11').notNull(),
    paymentHash: text('payment_hash').notNull(),
    amountMsat: num('amount_msat').notNull(),
    description: text('description').notNull(),
    verifyUrl: text('verify_url'),
    status: invoiceStatus('status').notNull().default('pending'),
    expiresAt: ts('expires_at').notNull(),
    settledAt: ts('settled_at'),
    preimage: text('preimage'),
    // The period this payment covers: projected when the invoice is made, final when it settles.
    periodStart: ts('period_start'),
    periodEnd: ts('period_end'),
    createdAt: createdAt(),
  },
  (t) => [
    check('sub_invoices_months', sql`${t.months} in (1, 3, 12)`),
    check('sub_invoices_hash_hex', sql`${t.paymentHash} ~ '^[0-9a-f]{64}$'`),
    check(
      'sub_invoices_amount',
      sql`${t.amountSat} > 0 and ${t.amountMsat} = ${t.amountSat} * 1000`,
    ),
    unique('sub_invoices_wallet_hash').on(t.walletConnectionId, t.paymentHash),
    index('subscription_invoices_by_vendor').on(t.vendorId, t.createdAt.desc()),
    index('subscription_invoices_pending_expiry')
      .on(t.expiresAt)
      .where(sql`${t.status} = 'pending'`),
  ],
);

export const usageCounters = core.table(
  'usage_counters',
  {
    vendorId: uuid('vendor_id')
      .notNull()
      .references(() => vendors.id),
    metric: text('metric', { enum: ['agent_turns', 'drafts'] }).notNull(),
    month: date('month').notNull(),
    used: integer('used').notNull().default(0),
  },
  (t) => [
    primaryKey({ columns: [t.vendorId, t.metric, t.month] }),
    check('usage_nonneg', sql`${t.used} >= 0`),
  ],
);

export const trialClaims = core.table('trial_claims', {
  claimKey: text('claim_key').primaryKey(),
  vendorId: uuid('vendor_id')
    .notNull()
    .references(() => vendors.id),
  claimedAt: ts('claimed_at').notNull().defaultNow(),
});

// ---------------------------------------------------------------- drafts, outbox, idempotency, audit

export const productDrafts = core.table('product_drafts', {
  id: id(),
  vendorId: uuid('vendor_id')
    .notNull()
    .references(() => vendors.id),
  source: text('source', { enum: ['dashboard', 'assistant'] }).notNull(),
  imageKeys: text('image_keys').array().notNull().default(sql`'{}'`),
  inputText: text('input_text'),
  extracted: jsonb('extracted').$type<Record<string, unknown>>(),
  questions: jsonb('questions').$type<unknown[]>().notNull().default([]),
  targetProductId: uuid('target_product_id').references(() => products.id),
  status: text('status', {
    enum: ['processing', 'needs_review', 'confirmed', 'discarded', 'failed'],
  })
    .notNull()
    .default('processing'),
  error: text('error'),
  createdAt: createdAt(),
  confirmedAt: ts('confirmed_at'),
});

export const outbox = core.table('outbox', {
  id: id(),
  topic: text('topic').notNull(),
  key: text('key').notNull(),
  payload: jsonb('payload').$type<Record<string, unknown>>().notNull(),
  createdAt: createdAt(),
  nextAttemptAt: ts('next_attempt_at').notNull().defaultNow(),
  attempts: integer('attempts').notNull().default(0),
  publishedAt: ts('published_at'),
  lastError: text('last_error'),
});

export const idempotencyKeys = core.table(
  'idempotency_keys',
  {
    scope: text('scope').notNull(),
    key: text('key').notNull(),
    requestHash: bytea('request_hash').notNull(),
    statusCode: smallint('status_code'),
    response: jsonb('response').$type<unknown>(),
    createdAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.scope, t.key] })],
);

export const auditLog = core.table('audit_log', {
  id: id(),
  actor: text('actor').notNull(),
  action: text('action').notNull(),
  target: text('target'),
  details: jsonb('details').$type<Record<string, unknown>>().notNull().default({}),
  createdAt: createdAt(),
});

// ---------------------------------------------------------------- vendor notifications

/**
 * What the vendor's dashboard is told about: order and wallet events from core, chat handoffs from the agent.
 * Read by the dashboard's SSE stream (and later sent as Web Push). Kept a few days. Separate from the outbox,
 * whose every row is delivered to the agent.
 */
export const vendorNotifications = core.table(
  'vendor_notifications',
  {
    id: id(),
    vendorId: uuid('vendor_id')
      .notNull()
      .references(() => vendors.id),
    type: text('type').notNull(),
    data: jsonb('data').$type<Record<string, unknown>>().notNull().default({}),
    /** Groups repeats (one per conversation every 5 minutes for handoffs). */
    dedupeKey: text('dedupe_key'),
    createdAt: createdAt(),
  },
  (t) => [index('vendor_notifications_stream').on(t.vendorId, t.id)],
);

/** A browser that allowed Web Push for a vendor (PushManager.subscribe). The endpoint is unique per browser. */
export const pushSubscriptions = core.table(
  'push_subscriptions',
  {
    id: id(),
    vendorId: uuid('vendor_id')
      .notNull()
      .references(() => vendors.id),
    endpoint: text('endpoint').notNull().unique(),
    p256dh: text('p256dh').notNull(),
    auth: text('auth').notNull(),
    expirationTime: ts('expiration_time'),
    createdAt: createdAt(),
    lastError: text('last_error'),
    revokedAt: ts('revoked_at'),
  },
  (t) => [index('push_subscriptions_by_vendor').on(t.vendorId)],
);
